import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.regex.Pattern;
import org.jlinalg.genetics.RfmixOutputAudit;
import static org.jlinalg.cli.NextflowFiles.*;
import static org.jlinalg.cli.AllcoolsPosteriorRequest.require;
import static org.jlinalg.cli.AllcoolsPosteriorCompute.map;

/** Complete immutable inputs, original inference and fresh saved-input replay. */
final class RfmixBundle {
    private RfmixBundle() { }
    static Runnable bounded(RfmixRequest.Spec spec,Runnable cancellation){long start=System.nanoTime();return ()->{cancellation.run();if(Thread.currentThread().isInterrupted()||(System.nanoTime()-start)/1000000>spec.wallMillis())throw new IllegalStateException("RFMix total wall capacity/cancellation exceeded");};}
    private static String input(Path path,String chosen,Map<Path,Map<String,Object>> rows,RfmixRequest.Spec spec,long[] total,Runnable check)throws IOException{
        if(!Files.isRegularFile(path)||!Files.isReadable(path))throw new RfmixRuntime.Unavailable("Complete permitted RFMix input unavailable: "+path+". Supply the named file before retrying; dependent analysis skipped");require(!rows.containsKey(path),"Input roles must identify distinct original files");Pin p=pin(path,spec.inputBytes(),check);total[0]=Math.addExact(total[0],p.bytes());require(total[0]<=spec.inputBytes(),"Complete original input byte capacity exceeded");rows.put(path,map("original",path.toString(),"captured",chosen,"bytes",p.bytes(),"sha256",p.sha256()));return chosen;
    }
    private static String genotype(RfmixRequest.Genotypes g,String role,Map<Path,Map<String,Object>> rows,RfmixRequest.Spec spec,long[] total,Runnable check)throws IOException{
        String name=role+switch(g.format()){case "vcf"->".vcf";case "vcf-gzip"->".vcf.gz";case "bcf"->".bcf";default->throw new IOException("Unsupported input format");};input(g.path(),name,rows,spec,total,check);if(g.index()!=null)input(g.index(),name+".csi",rows,spec,total,check);return name;
    }
    static Path capture(Path supplied,RfmixRequest.Spec spec,Runnable cancellation)throws IOException{
        RfmixRuntime.platform();Runnable check=bounded(spec,cancellation);Pin producingJar=RfmixRuntime.producer();var runtime=RfmixRuntime.open(spec.runtime(),spec.profile(),check);if(spec.query().format().equals("bcf")||spec.reference().format().equals("bcf"))runtime.helper("bcftools");Path root=RfmixRuntime.newRoot(supplied);runtime.separate(root);require(!root.startsWith(spec.runtime())&&!spec.runtime().startsWith(root),"Capture/runtime paths overlap");var rows=new LinkedHashMap<Path,Map<String,Object>>();long[] total={0};String query=genotype(spec.query(),"query",rows,spec,total,check),reference=genotype(spec.reference(),"reference",rows,spec,total,check),sampleMap=input(spec.sampleMap(),spec.compressedMap()?"sample-map.tsv.gz":"sample-map.tsv",rows,spec,total,check),geneticMap=input(spec.geneticMap(),"genetic-map.tsv",rows,spec,total,check);
        for(Path original:rows.keySet())require(!original.startsWith(root)&&!root.startsWith(original),"Capture/input paths overlap");Files.createDirectory(root);
        try{
            Files.writeString(root.resolve("WARNINGS.md"),RfmixRuntime.ACTION,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);writeJson(root.resolve("request.json"),spec.value());writeJson(root.resolve("source-inputs.json"),new ArrayList<>(rows.values()));writeJson(root.resolve("runtime-binding.json"),map("path",spec.runtime().toString(),"seal",runtime.seal()));Path engine=Files.createDirectory(root.resolve("engine")),inputs=Files.createDirectory(engine.resolve("inputs"));for(var row:rows.entrySet()){check.run();Path target=inputs.resolve(text(row.getValue().get("captured")));Files.copy(row.getKey(),target);require(pin(target,spec.inputBytes(),check).equals(fingerprint(row.getValue(),spec.inputBytes())),"Captured original input differs from its complete pre-copy identity");}
            writeJson(root.resolve("captured-inputs.json"),manifest(tree(inputs,spec.files(),spec.inputBytes(),spec.inputBytes(),check)));writeJson(engine.resolve("effective.json"),map("query",query,"reference",reference,"sample_map",sampleMap,"genetic_map",geneticMap,"source_arguments",spec.arguments(),"settings",spec.settings()));writeJson(engine.resolve("profile.json"),RfmixRuntime.profile(spec.profile()));
            execute(root,spec,runtime,check);for(var row:rows.entrySet())require(pin(row.getKey(),spec.inputBytes(),check).equals(fingerprint(row.getValue(),spec.inputBytes())),"Original input changed during RFMix workflow");runtime.verify(check);require(producingJar.equals(RfmixRuntime.producer()),"Producing JAR changed during complete workflow");
            writeJson(root.resolve("manifest.json"),map("producer",producingJar,"files",manifest(tree(root,spec.files(),spec.process().workspaceBytes(),Math.max(Math.max(spec.inputBytes(),spec.decodedBytes()),spec.outputBytes()),check)),"whole_package_admitted",false));writeJson(root.resolve("COMPLETED.json"),map("status","COMPLETE_RFMIX_MSP_FB_Q_WORKFLOW_SIS_UNQUALIFIED","analysis_admitted","MSP_FB_Q_ONLY","sis_dependent_analysis","SKIPPED_ORIGINAL_WRITER_FINAL_ITERATION_UNQUALIFIED","fresh_replay_required",true,"whole_package_admitted",false,"manifest",pin(root.resolve("manifest.json"),134217728,check)));return root;
        }catch(IOException|RuntimeException|Error e){failure(root,e);throw e;}
    }
    private static NextflowProcess.Check integrity(Path root,RfmixRequest.Spec spec,RfmixRuntime.Context runtime,Runnable check)throws IOException{
        Object expected=json(root.resolve("captured-inputs.json"),134217728),effective=json(root.resolve("engine/effective.json"),16777216);Pin producer=RfmixRuntime.producer();return ()->{check.run();require(producer.equals(RfmixRuntime.producer()),"Producing JAR changed");require(NextflowJson.json(expected).equals(NextflowJson.json(manifest(tree(root.resolve("engine/inputs"),spec.files(),spec.inputBytes(),spec.inputBytes(),check)))),"Complete captured input bytes/population changed");require(NextflowJson.json(effective).equals(NextflowJson.json(json(root.resolve("engine/effective.json"),16777216))),"Effective source settings changed");require(NextflowJson.json(RfmixRuntime.profile(spec.profile())).equals(NextflowJson.json(json(root.resolve("engine/profile.json"),16777216))),"Source profile changed");runtime.verify(check);};
    }
    private static void process(Path root,RfmixRequest.Spec spec,RfmixRuntime.Context runtime,String name,List<String> args,Runnable check)throws IOException{NextflowProcess.executeSession(args,runtime.executionEnvironment(),root.resolve("engine/"+name),root.resolve("engine"),root,spec.process(),integrity(root,spec,runtime,check),check);}
    private static Path decode(Path root,String name,String format,RfmixRequest.Spec spec,RfmixRuntime.Context runtime,String role,Runnable check)throws IOException{
        Path path=root.resolve("engine/inputs").resolve(name);if(format.equals("vcf-gzip"))process(root,spec,runtime,role+"-gzip-check",List.of(runtime.helper("gzip"),"-t","--",path.toString()),check);
        if(!format.equals("bcf"))return path;Path decoded=root.resolve("engine/"+role+"-decoded.vcf");process(root,spec,runtime,role+"-bcf-decode",List.of(runtime.helper("bcftools"),"view","--no-version","-Ov","-o",decoded.toString(),path.toString()),check);pin(decoded,spec.decodedBytes(),check);return decoded;
    }
    private static void execute(Path root,RfmixRequest.Spec spec,RfmixRuntime.Context runtime,Runnable check)throws IOException{
        var effective=object(json(root.resolve("engine/effective.json"),16777216));require(NextflowJson.json(spec.arguments()).equals(NextflowJson.json(effective.get("source_arguments")))&&NextflowJson.json(spec.settings()).equals(NextflowJson.json(effective.get("settings"))),"Saved effective settings differ from typed request");Path query=decode(root,text(effective.get("query")),spec.query().format(),spec,runtime,"query",check),reference=decode(root,text(effective.get("reference")),spec.reference().format(),spec,runtime,"reference",check),sampleMap=root.resolve("engine/inputs").resolve(text(effective.get("sample_map"))),geneticMap=root.resolve("engine/inputs").resolve(text(effective.get("genetic_map")));
        if(spec.compressedMap())process(root,spec,runtime,"sample-map-gzip-check",List.of(runtime.helper("gzip"),"-t","--",sampleMap.toString()),check);
        var inputs=RfmixInputs.audit(query,spec.query().format().equals("vcf-gzip"),reference,spec.reference().format().equals("vcf-gzip"),sampleMap,spec.compressedMap(),geneticMap,spec,check);writeJson(root.resolve("INPUT-AUDIT.json"),inputs.audit());
        Path engine=root.resolve("engine");var command=new ArrayList<String>(List.of(runtime.executable(),"-f",engine.resolve("inputs").resolve(text(effective.get("query"))).toString(),"-r",engine.resolve("inputs").resolve(text(effective.get("reference"))).toString(),"-m",sampleMap.toString(),"-g",geneticMap.toString(),"-o",engine.resolve("ancestry").toString()));command.addAll(spec.arguments());process(root,spec,runtime,"inference-process",command,check);
        var report=RfmixOutputAudit.audit(engine.resolve("ancestry.msp.tsv"),engine.resolve("ancestry.fb.tsv"),engine.resolve("ancestry.rfmix.Q"),engine.resolve("ancestry.sis.tsv"),inputs.contract(),new RfmixOutputAudit.Limits(spec.outputBytes(),spec.lineCharacters(),spec.variants(),spec.samples(),spec.populations(),spec.cells()));check.run();require(report.populations().equals(inputs.audit().get("populations_original_C_locale_order")),"Original population code order differs from independent sample-map C-locale census");var audit=report(report);var source=sourceLog(engine.resolve("inference-process/process.stderr"),spec,check);audit.put("source_execution",source);var warnings=new ArrayList<String>(inputs.warnings());for(Object warning:list(source.get("warnings")))warnings.add("Original RFMix: "+text(warning));warnings.addAll(report.warnings());warnings.add("SIS-DEPENDENT ANALYSIS SKIPPED: original SIS bytes are retained and numerically inspected, but final-iteration probabilities are not certified. MSP/FB/Q completion does not admit SIS analysis.");audit.put("warnings",warnings);writeJson(root.resolve("OUTPUT-AUDIT.json"),audit);Files.writeString(root.resolve("WARNINGS.md"),"\n"+String.join("\n",warnings)+"\n",StandardCharsets.UTF_8,StandardOpenOption.APPEND);writeJson(root.resolve("canonical.json"),canonical(engine,spec,check));
    }
    static Map<String,Object> report(RfmixOutputAudit.Report r){var files=new TreeMap<String,Object>();r.files().forEach((name,p)->files.put(name,map("bytes",p.bytes(),"sha256",p.sha256())));return map("status","PASS_COMPLETE_RFMIX_MSP_FB_Q_CENSUS_AND_CROSS_TABLE_AUDIT","populations",r.populations(),"retained_loci",r.retainedLoci(),"markers",r.markers(),"segments",r.segments(),"query_samples",r.querySamples(),"q_rows",r.qRows(),"posterior_cells",r.posteriorCells(),"q_cells",r.qCells(),"query_fractions_from_equal_MSP_marker_weights",r.queryFractionsFromMspMarkers(),"sis",map("rows",r.sis().rows(),"header_columns",r.sis().headerColumns(),"data_columns",r.sis().dataColumns(),"source_header_data_mismatch",r.sis().sourceHeaderDataMismatch(),"final_iteration_certified",false,"dependent_analysis","SKIPPED"),"files",files,"whole_package_admitted",false);}
    private static Map<String,Object> sourceLog(Path path,RfmixRequest.Spec spec,Runnable check)throws IOException{
        pin(path,Math.min(spec.outputBytes(),268435456),check);String log=utf8(bytes(path,(int)Math.min(spec.outputBytes(),268435456)));var traces=new ArrayList<Object>();var pattern=Pattern.compile("EM iteration ([0-9]+)/([0-9]+) - logl = ([^ ]+) \\(([^)]+)\\)");var sourceWarnings=new ArrayList<String>();Double initial=null;var initialPattern=Pattern.compile("Initial analysis - logl ([^ ]+)");int last=0;for(String line:log.split("\\r?\\n",-1)){check.run();var first=initialPattern.matcher(line);if(first.matches()){require(initial==null,"Repeated original initial objective");initial=finite(first.group(1));}if(line.toLowerCase(Locale.ROOT).matches(".*(?:warning|error|unphased).*"))sourceWarnings.add(line);var m=pattern.matcher(line);if(m.matches()){int iteration=Integer.parseInt(m.group(1));require(iteration==last+1&&Integer.parseInt(m.group(2))==spec.em()&&iteration<=spec.em(),"Original EM iteration ledger differs from request");double objective=finite(m.group(3)),gain=finite(m.group(4));traces.add(map("iteration",iteration,"printed_log_likelihood",objective,"printed_change",gain));last=iteration;}if(line.toLowerCase(Locale.ROOT).matches(".*(?:logl|likelihood|weight).*(?:nan|[+-]?inf(?:inity)?)(?:[^a-z].*|$)"))throw new IOException("Nonfinite original model objective/weight; inspect original stderr");}
        require(initial!=null,"Original initial analysis has no complete finite objective trace");require(spec.em()==0||last>0,"Requested EM has no complete finite iteration trace");boolean early=last<spec.em();if(early)require(log.contains("EM converges at iteration "+last),"Original EM stopped without its declared termination message");return map("initial_printed_log_likelihood",initial,"warnings",sourceWarnings,"requested_em_iterations",spec.em(),"actual_em_iterations",last,"original_reported_early_stop",early,"em_trace_printed_source_precision",traces,"statistical_convergence_certified",false,"termination_interpretation","Original stops when likelihood gain <0.1, including a negative gain; exit zero/printed convergence is not an independent convergence certificate. Complete original stderr retained.");
    }
    private static double finite(String value)throws IOException{try{double n=Double.parseDouble(value);require(Double.isFinite(n),"Nonfinite original model trace");return n;}catch(NumberFormatException e){throw new IOException("Invalid original model trace",e);}}
    private static Map<String,Object> canonical(Path engine,RfmixRequest.Spec spec,Runnable check)throws IOException{var files=new TreeMap<String,Object>();for(String suffix:List.of("msp.tsv","fb.tsv","rfmix.Q","sis.tsv")){Pin p=pin(engine.resolve("ancestry."+suffix),spec.outputBytes(),check);files.put(suffix,map("bytes",p.bytes(),"sha256",p.sha256()));}return files;}
    static void verify(Path supplied,Path scratchSupplied,Runnable cancellation)throws IOException{
        RfmixRuntime.platform();Path root=directory(supplied.toAbsolutePath().normalize());var spec=RfmixRequest.read(root.resolve("request.json"));Runnable check=bounded(spec,cancellation);var done=object(json(root.resolve("COMPLETED.json"),1048576));require("COMPLETE_RFMIX_MSP_FB_Q_WORKFLOW_SIS_UNQUALIFIED".equals(done.get("status"))&&!Files.exists(root.resolve("FAILURE.json")),"Only complete core captures may be replayed");require(pin(root.resolve("manifest.json"),134217728,check).equals(fingerprint(done.get("manifest"),134217728)),"Capture manifest changed");var saved=object(json(root.resolve("manifest.json"),134217728));require(RfmixRuntime.producer().equals(fingerprint(saved.get("producer"),1000000000L)),"Restore exact producing JAR; never refresh old seals");var actual=new TreeMap<>(manifest(tree(root,spec.files(),spec.process().workspaceBytes(),Math.max(Math.max(spec.inputBytes(),spec.decodedBytes()),spec.outputBytes()),check)));actual.remove("manifest.json");actual.remove("COMPLETED.json");require(NextflowJson.json(actual).equals(NextflowJson.json(saved.get("files"))),"Complete saved capture population/bytes changed");
        var runtime=RfmixRuntime.open(spec.runtime(),spec.profile(),check);var binding=object(json(root.resolve("runtime-binding.json"),1048576));require(spec.runtime().toString().equals(binding.get("path"))&&runtime.seal().equals(fingerprint(binding.get("seal"),1048576)),"Saved runtime binding changed");Path scratch=RfmixRuntime.newRoot(scratchSupplied);runtime.separate(scratch);require(!scratch.startsWith(root)&&!root.startsWith(scratch)&&!scratch.startsWith(spec.runtime())&&!spec.runtime().startsWith(scratch),"Replay must be separate from capture/runtime");Files.createDirectory(scratch);
        try{
            Files.writeString(scratch.resolve("WARNINGS.md"),RfmixRuntime.ACTION,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);Files.copy(root.resolve("captured-inputs.json"),scratch.resolve("captured-inputs.json"));Path engine=Files.createDirectory(scratch.resolve("engine")),inputs=Files.createDirectory(engine.resolve("inputs"));try(var children=Files.newDirectoryStream(root.resolve("engine/inputs"))){for(Path path:children){check.run();Files.copy(path,inputs.resolve(path.getFileName()));}}for(String name:List.of("effective.json","profile.json"))Files.copy(root.resolve("engine/"+name),engine.resolve(name));execute(scratch,spec,runtime,check);
            for(String name:List.of("INPUT-AUDIT.json","OUTPUT-AUDIT.json","canonical.json"))require(NextflowJson.json(json(scratch.resolve(name),134217728)).equals(NextflowJson.json(json(root.resolve(name),134217728))),"Fresh complete original inference/native audit differs: "+name);runtime.verify(check);writeJson(scratch.resolve("COMPLETED.json"),map("status","PASS_COMPLETE_RFMIX_BINARY_AND_NUMERICAL_REPLAY","original_capture",root.toString(),"sis_dependent_analysis","SKIPPED_ORIGINAL_WRITER_FINAL_ITERATION_UNQUALIFIED","whole_package_admitted",false));
        }catch(IOException|RuntimeException|Error e){failure(scratch,e);throw e;}
    }
    private static void failure(Path root,Throwable e)throws IOException{writeJson(root.resolve("FAILURE.json"),map("status",e instanceof RfmixRuntime.Unavailable||e instanceof NextflowProcess.Unavailable?"SKIP3_DEPENDENT_RFMIX_ANALYSIS_SKIPPED":"FAIL2_NO_COMPLETE_RFMIX_WORKFLOW","error",e.toString(),"analysis_admitted",false,"required_action",RfmixRuntime.ACTION));}
}
